65	    /**
66	     * Given args, infers the appropriate instantiation of a generic function:
67	     * the one inferWithCoercion finds, or, when it finds none, the one
68	     * inferByUnification finds.
69	     *
70	     * @throws ProgramError
71	     */
72	    public static Simple_fcn inferAndInstantiateGenericFunction(List<FValue> args,
73	                                                                GenericFunctionOrMethod appliedThing,
74	                                                                Environment envForInference) throws ProgramError {
75	        BigOperatorHint h = choosing.get();
76	        return inferAndInstantiateGenericFunction(args, appliedThing, envForInference,
77	                                                  h != null && h.covers(appliedThing) ? h : null);
78	    }
