80	    /**
81	     * As above, a big operator under the hint h of a reduction or a
82	     * comprehension that writes no static argument, where h is not null: the
83	     * instance that the hint gives, where inferWithCoercion finds one, and
84	     * otherwise the instance that no hint gives.
85	     */
86	    static Simple_fcn inferAndInstantiateGenericFunction(List<FValue> args,
87	                                                         GenericFunctionOrMethod appliedThing,
88	                                                         Environment envForInference,
89	                                                         BigOperatorHint h) throws ProgramError {
90	        Simple_fcn sfcn = h != null && bigOperator(appliedThing) ?
91	                          inferWithCoercion(args, appliedThing, envForInference, h) : null;
92	        if (sfcn == null) sfcn = inferWithCoercion(args, appliedThing, envForInference, null);
93	        return sfcn != null ? sfcn : inferByUnification(args, appliedThing, envForInference, true);
94	    }
