123	    /**
124	     * A bounding map for a call's static parameters.  With bounded, where a
125	     * type joined into a lower bound has several minimal common supertypes
126	     * with it, or none, and both lie under the upper bound, the lower bound
127	     * becomes that upper bound, Any where there is none: the type parameter
128	     * takes its bound, not one of those supertypes.  Without, the lattice's
129	     * join decides, as when a declaration is chosen.
130	     */
131	    static final class BoundingIntervals extends LatticeIntervalMap<String, FType, TypeLatticeOps> {
132	        private final boolean bounded;
133	
134	        BoundingIntervals(boolean bounded) {
135	            super(TypeLatticeOps.V, DefaultComparator.V);
136	            this.bounded = bounded;
137	        }
138	
139	        @Override
140	        public FType joinPut(String k, FType v) {
141	            FType lower = bounded ? getLower(k) : null;
142	            if (lower != null && lower.join(v).size() != 1) {
143	                FType upper = getUpper(k);
144	                FType bound = upper == null ? FTypeTop.ONLY : upper;
145	                if (lower.subtypeOf(bound) && v.subtypeOf(bound)) {
146	                    traceInstance("several", k, k, lower + " join " + v, bound, "");
147	                    putPair(k, bound, bound);
148	                    return bound;
149	                }
150	            }
151	            return super.joinPut(k, v);
152	        }
153	    }
