164	    /**
165	     * What instantiates the big operator of a reduction or a comprehension
166	     * that writes no static argument, the run-time counterpart of the
167	     * desugaring by the type of the expression: the declared type of the
168	     * variable or the declared return type of the function whose value the
169	     * clause form is (expected), which constrains the instance as a call's
170	     * static return type does, and else the join of the run-time types of
171	     * the elements that its generator clauses gave (elements).  Either may be
172	     * null.  It names the operator value it is for, and it is passed to that
173	     * operator's instantiation alone (instantiateBigOperator).
174	     */
175	    public static final class BigOperatorHint {
176	        final FValue operator;
177	        final FType elements;
178	        final FType expected;
179	        private volatile boolean byExpected;
180	
181	        public BigOperatorHint(FValue operator, FType elements, FType expected) {
182	            this.operator = operator;
183	            this.elements = elements;
184	            this.expected = expected;
185	        }
186	
187	        /** Whether the instance was fixed by the declared type. */
188	        public boolean byExpected() {
189	            return byExpected;
190	        }
191	
192	        /** Whether g is the operator, or one of its overloads. */
193	        boolean covers(GenericFunctionOrMethod g) {
194	            if (operator == g) return true;
195	            if (!(operator instanceof OverloadedFunction)) return false;
196	            for (Overload o : ((OverloadedFunction) operator).getOverloads()) if (o.getFn() == g) return true;
197	            return false;
198	        }
199	    }
