201	    /**
202	     * The hint of the overloaded big operator whose overload this thread is
203	     * choosing and instantiating, set by instantiateBigOperator around
204	     * OverloadedFunction.bestMatch alone.  bestMatch evaluates no Fortress
205	     * expression and starts and joins no task, so no other evaluation runs on
206	     * this thread while it is set; inferAndInstantiateGenericFunction reads it
207	     * only for an overload of the operator it names.
208	     */
209	    private static final ThreadLocal<BigOperatorHint> choosing = new ThreadLocal<BigOperatorHint>();
210	
211	    /**
212	     * Whether a reduction's or a comprehension's big operator value opv has
213	     * static parameters to instantiate: a generic function, or an overloaded
214	     * one with a generic overload.
215	     */
216	    public static boolean instantiable(FValue opv) {
217	        if (opv instanceof GenericFunctionOrConstructor) return true;
218	        if (!(opv instanceof OverloadedFunction)) return false;
219	        for (Overload o : ((OverloadedFunction) opv).getOverloads()) {
220	            if (o.getFn() instanceof GenericFunctionOrMethod) return true;
221	        }
222	        return false;
223	    }
