225	    /**
226	     * The big operator value opv, which instantiable accepts, applied to no
227	     * argument as a reduction or a comprehension that writes no static
228	     * argument applies it: the declaration is chosen and instantiated under
229	     * the hint h, outside the per-argument-type caches, which hold the
230	     * instance that no hint gives, and the instance is then applied with no
231	     * hint in reach.
232	     */
233	    public static FValue instantiateBigOperator(FValue opv, BigOperatorHint h, HasAt site) {
234	        List<FValue> none = Collections.<FValue>emptyList();
235	        SingleFcn inst;
236	        try {
237	            if (opv instanceof GenericFunctionOrConstructor) {
238	                GenericFunctionOrConstructor g = (GenericFunctionOrConstructor) opv;
239	                inst = inferAndInstantiateGenericFunction(none, g, g.getWithin(), h);
240	            } else {
241	                OverloadedFunction of = (OverloadedFunction) opv;
242	                BigOperatorHint before = choosing.get();
243	                choosing.set(h);
244	                try {
245	                    inst = of.bestMatch(none, of.getOverloads());
246	                }
247	                finally {
248	                    if (before == null) choosing.remove();
249	                    else choosing.set(before);
250	                }
251	                if (inst instanceof GenericFunctionOrMethod) {
252	                    return bug(site, errorMsg("overload res yielded generic ", inst));
253	                }
254	            }
255	        }
256	        catch (FortressException ex) {
257	            throw ex.setWhere(site);
258	        }
259	        return inst.functionInvocation(none, site);
260	    }
