263	     * The join of the run-time types of the elements that the library's
264	     * collector __elemsOf gave, the static argument of its __Elems[\T\]; null
265	     * where it gave no element.
266	     */
267	    public static FType elementsType(FValue elems) {
268	        if (!(elems.type() instanceof GenericTypeInstance)) return null;
269	        List<FType> ps = ((GenericTypeInstance) elems.type()).getTypeParams();
270	        return ps.size() == 1 ? ps.get(0) : null;
