273	    /**
274	     * The static argument at position k of a big operator's declared result,
275	     * where it is one of the library's BigReduction, Comprehension or
276	     * BigOperator, or of the one of those three that the declared result
277	     * extends (libraryBigResult); null otherwise.  For the element type I, k
278	     * is 0 in each; for the result type O, k is 0 in BigReduction[\R,L\],
279	     * whose O is R, and 1 in the other two.
280	     */
281	    private static Type resultArgOf(GenericFunctionOrMethod g, boolean result) {
282	        Option<Type> rt = g.getReturnType();
283	        if (rt.isNone() || !(rt.unwrap() instanceof TraitType)) return null;
284	        TraitType tt = libraryBigResult((TraitType) rt.unwrap(), g.getWithin(), 0);
285	        if (tt == null) return null;
286	        int k = bareName(tt).equals("BigReduction") ? 0 : result ? 1 : 0;
287	        List<StaticArg> sas = tt.getArgs();
288	        if (sas.size() <= k || !(sas.get(k) instanceof TypeArg)) return null;
289	        return ((TypeArg) sas.get(k)).getTypeArg();
290	    }
