292	    /** The name of the trait tt, without the api that qualifies it. */
293	    private static String bareName(TraitType tt) {
294	        String head = NodeUtil.nameString(tt.getName());
295	        int dot = head.lastIndexOf('.');
296	        return dot >= 0 ? head.substring(dot + 1) : head;
297	    }
