299	    /** How many declarations up the extends clauses libraryBigResult reads. */
300	    private static final int BIG_RESULT_DEPTH = 16;
301	
302	    /**
303	     * The type tt, named in the environment env, where it is the library's
304	     * BigReduction, Comprehension or BigOperator; else the first of those
305	     * three that tt extends, read through the extends clause of tt's trait
306	     * or object declaration and up its supertypes' in turn, each with tt's
307	     * static arguments put for the declaration's static parameters; null
308	     * where none is found.
309	     */
310	    private static TraitType libraryBigResult(TraitType tt, Environment env, int depth) {
311	        String head = bareName(tt);
312	        if (head.equals("BigReduction") || head.equals("Comprehension") || head.equals("BigOperator")) return tt;
313	        if (depth >= BIG_RESULT_DEPTH) return null;
314	        FType ft;
315	        try {
316	            ft = env.getType(tt);
317	        }
318	        catch (FortressException ex) {
319	            return null;
320	        }
321	        if (!(ft instanceof FTraitOrObjectOrGeneric)) return null;
322	        FTraitOrObjectOrGeneric declared = (FTraitOrObjectOrGeneric) ft;
323	        Object d = declared instanceof FTypeGeneric ? ((FTypeGeneric) declared).getDef() : declared.getDecl();
324	        if (!(d instanceof TraitObjectDecl)) return null;
325	        TraitObjectDecl decl = (TraitObjectDecl) d;
326	        List<StaticParam> sps = NodeUtil.getStaticParams(decl);
327	        if (sps.size() != tt.getArgs().size()) return null;
328	        StaticTypeReplacer args = new StaticTypeReplacer(sps, tt.getArgs());
329	        for (TraitTypeWhere ttw : NodeUtil.getExtendsClause(decl)) {
330	            Type sup = args.replaceIn(ttw.getBaseType());
331	            if (!(sup instanceof TraitType)) continue;
332	            TraitType found = libraryBigResult((TraitType) sup, declared.getWithin(), depth + 1);
333	            if (found != null) return found;
334	        }
335	        return null;
336	    }
