338	    /**
339	     * Whether g is a big operator, whose static parameters a reduction or a
340	     * comprehension that writes none leaves to the declared type of its value
341	     * or to the elements its generator clauses produce (BigOperatorHint).
342	     */
343	    private static boolean bigOperator(GenericFunctionOrMethod g) {
344	        if (!(g.getName() instanceof Op)) return false;
345	        Op op = (Op) g.getName();
346	        return op.getFixity() instanceof BigFixity || op.getText().startsWith("BIG ");
