349	    /**
350	     * The instance of each static parameter: its lower bound in abm, except
351	     * that, with bounded, a type parameter that the arguments do not fix, or
352	     * that they bound only from above (aboveOnly), takes its bound: where its
353	     * bounds mention no static parameter (rechecks), its interval's upper end;
354	     * where they mention others but not itself, its bounds at their instances.  The arguments fix
355	     * a type parameter that an argument's declared parameter type mentions
356	     * (fixable), and one that a bound of a type parameter they fix mentions.
357	     * With bounded, a type parameter that the arguments do not fix and whose
358	     * bound mentions the parameter itself, of any declaration, a big
359	     * operator's included, is left open (BottomType.OPEN).  Any other left
360	     * open is BottomType.
361	     */
362	    private static ArrayList<FType> instanceOf(List<StaticParam> tparams,
363	                                               LatticeIntervalMap<String, FType, TypeLatticeOps> abm,
364	                                               Set<String> fixable, Set<String> aboveOnly,
365	                                               Collection<StaticParam> rechecks,
366	                                               boolean bounded, GenericFunctionOrMethod appliedThing,
367	                                               List<FValue> args) {
368	        ArrayList<FType> tl = new ArrayList<FType>(tparams.size());
369	        Set<String> fixed = bounded ? fixedThroughBounds(tparams, fixable) : fixable;
370	        for (StaticParam tp : tparams) {
371	            String n = NodeUtil.getName(tp);
372	            FType t = abm.get(n);
373	            boolean unfixed = !fixed.contains(n);
374	            if (bounded && NodeUtil.isTypeParam(tp) && (unfixed || aboveOnly.contains(n)) &&
375	                (rechecks == null || !rechecks.contains(tp)) && (t == null || t instanceof BottomType)) {
376	                t = boundOf(abm, n);
377	                traceInstance(unfixed ? "unfixed" : "above", appliedThing, n, BottomType.ONLY, t, typesOf(args));
378	            }
379	            if (t == null) t = BottomType.ONLY;
380	            tl.add(t);
381	        }
382	        if (bounded && rechecks != null) {
383	            Set<String> fixedAll = fixedThroughBounds(tparams, fixable);
384	            for (int i = 0; i < tparams.size(); i++) {
385	                StaticParam tp = tparams.get(i);
386	                String n = NodeUtil.getName(tp);
387	                if (!NodeUtil.isTypeParam(tp) || fixedAll.contains(n) || !rechecks.contains(tp) ||
388	                    !(tl.get(i) instanceof BottomType) || !mentionsItself(tp)) continue;
389	                traceInstance("open", appliedThing, n, BottomType.ONLY, BottomType.OPEN, typesOf(args));

390	                tl.set(i, BottomType.OPEN);
391	            }
392	        }
393	        if (!bounded || rechecks == null) return tl;
394	        for (int i = 0; i < tparams.size(); i++) {
395	            StaticParam tp = tparams.get(i);
396	            String n = NodeUtil.getName(tp);
397	            if (!NodeUtil.isTypeParam(tp) || fixed.contains(n) || !rechecks.contains(tp) ||
398	                !(tl.get(i) instanceof BottomType)) continue;
399	            FType b = boundAtInstances(tp, tparams, tl, appliedThing);
400	            if (b != null) {
401	                traceInstance("unfixed", appliedThing, n, BottomType.ONLY, b, typesOf(args));
402	                tl.set(i, b);
403	            }
404	        }
405	        return tl;
406	    }
