516	    /**
517	     * An instantiation of a generic function that admits every argument by
518	     * subtyping or by one coercion, or null.  An argument whose declared type
519	     * mentions a static parameter other than as the whole type is unified with
520	     * it; an argument whose declared type mentions no static parameter is left
521	     * to the coercion at binding; a type parameter that is the whole declared
522	     * type of some argument and that nothing else fixes takes the narrowest of
523	     * its arguments' types, the types they coerce to and its bounds that each
524	     * of those arguments is a subtype of or coerces to, and, when no one is
525	     * narrowest, its bound, where each of those arguments is a subtype of it;
526	     * one whose bound mentions a static parameter takes the narrowest of those
527	     * and of the arguments' supertypes, and otherwise the join of its
528	     * arguments' types.  A type parameter that no argument fixes takes its
529	     * bound (instanceOf).
530	     */
531	    private static Simple_fcn inferWithCoercion(List<FValue> args,
532	                                                GenericFunctionOrMethod appliedThing,
533	                                                Environment envForInference, BigOperatorHint h) {
534	        try {
535	            return inferWithCoercionOrFail(args, appliedThing, envForInference, h);
536	        }
537	        catch (FortressException ex) {
538	            return null;
539	        }
540	        catch (EmptyLatticeIntervalError ex) {
541	            return null;
542	        }
543	    }
