545	    private static Simple_fcn inferWithCoercionOrFail(List<FValue> args,
546	                                                      GenericFunctionOrMethod appliedThing,
547	                                                      Environment envForInference, BigOperatorHint h) {
548	        final List<FValue> originalArgs = args;
549	        GenericTypeInstance selfType = null;
550	        if (appliedThing instanceof GenericFunctionalMethod) {
551	            GenericFunctionalMethod gfm = (GenericFunctionalMethod) appliedThing;
552	            FTypeGeneric declaredSelfType = gfm.getSelfParameterTypeAsGeneric();
553	            FValue selfArg = args.get(gfm.getSelfParameterIndex());
554	            if (!(selfArg.type() instanceof GenericTypeInstance)) return null;
555	            selfType = (GenericTypeInstance) selfArg.type();
556	            for (FType ft : selfType.getTransitiveExtends()) {
557	                if (ft instanceof GenericTypeInstance && ((GenericTypeInstance) ft).getGeneric().equals(
558	                        declaredSelfType)) {
559	                    selfType = (GenericTypeInstance) ft;
560	                    break;
561	                }
562	            }
563	            envForInference = selfType.getWithin();
564	        }
565	        List<StaticParam> tparams = appliedThing.getStaticParams();
566	        List<Param> params = appliedThing.getParams();
567	        Environment declared = declarationEnv(appliedThing);
568	        EvalType et = new EvalType(declared);
569	        BoundingIntervals abm = new BoundingIntervals(true);
570	        Set<String> tp_set = new HashSet<String>();
571	        Set<String> typeParams = new HashSet<String>();
572	        Map<String, List<FType>> bounds = new HashMap<String, List<FType>>();
573	        List<StaticParam> rechecks = new ArrayList<StaticParam>();
574	        for (StaticParam sp : tparams) {
575	            String name = NodeUtil.getName(sp);
576	            tp_set.add(name);
577	            if (!NodeUtil.isTypeParam(sp)) continue;
578	            typeParams.add(name);
579	            List<FType> bs = new ArrayList<FType>();
580	            bounds.put(name, bs);
581	            for (Type tr : sp.getExtendsClause()) {
582	                try {
583	                    FType tt = et.evalType(tr);
584	                    abm.meetPut(name, tt);
585	                    bs.add(tt);
586	                }
587	                catch (FortressException pe) {
588	                    if (!rechecks.contains(sp)) rechecks.add(sp);
589	                }
590	            }
